  "inlineSchema": "// Prisma Schema using recommended conventions:\n// - Model names: Singular, PascalCase (e.g., User, Post)\n// - Field names (columns): camelCase (e.g., createdAt, authorId)\n// - Table names: Default Prisma mapping (PascalCase, matches Model name)\n// - Pivot tables: Clear combinations (e.g., PermissionRole)\n// - Added unique username field to User model.\n// - Reordered fields in Comment model for visual preference.\n// - Moved timestamp fields (createdAt, updatedAt) to the end of each model definition.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./node_modules/@prisma/client\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\") // Pastikan variabel ini benar di .env\n}\n\n// --- Core Authentication and Authorization Models ---\n\nmodel User {\n  id       Int     @id @default(autoincrement())\n  name     String?\n  username String  @unique // Username unik ditambahkan\n  email    String  @unique\n  password String // Menyimpan hash password\n\n  // Relations\n  posts       Post[] // Relasi ke postingan pengguna\n  comments    Comment[] // Relasi ke komentar pengguna\n  roles       UserRole[] // Relasi ke peran pengguna via tabel pivot\n  permissions UserPermission[] // Relasi ke izin langsung pengguna via tabel pivot\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Role {\n  id        Int    @id @default(autoincrement())\n  name      String @unique // contoh: \"admin\", \"author\", \"editor\"\n  guardName String @default(\"api\") @map(\"guard_name\") // Nama guard, map ke snake_case di DB jika diinginkan\n\n  // Relations\n  permissions PermissionRole[] // Relasi ke izin peran via tabel pivot\n  users       UserRole[] // Relasi ke pengguna dengan peran ini via tabel pivot\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Permission {\n  id        Int    @id @default(autoincrement())\n  name      String @unique // contoh: \"createPost\", \"publishPost\", \"manageUsers\" (camelCase)\n  guardName String @default(\"api\") @map(\"guard_name\") // Nama guard\n\n  // Relations\n  roles PermissionRole[] // Relasi ke peran dengan izin ini via tabel pivot\n  users UserPermission[] // Relasi ke pengguna dengan izin ini via tabel pivot\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// --- Pivot Tables for RBAC ---\n// Note: Pivot tables often don't need explicit timestamps,\n// but you could add them if tracking when relations were created/modified is important.\n\nmodel PermissionRole {\n  permissionId Int\n  roleId       Int\n\n  // Relations\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  // Map nama tabel pivot jika ingin snake_case di DB\n  // @@map(\"permission_roles\")\n\n  // Composite primary key\n  @@id([permissionId, roleId])\n  // Optional index\n  @@index([roleId])\n}\n\nmodel UserRole {\n  userId Int\n  roleId Int\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role Role @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  // @@map(\"user_roles\")\n\n  // Composite primary key\n  @@id([userId, roleId])\n  // Optional index\n  @@index([roleId])\n}\n\nmodel UserPermission {\n  userId       Int\n  permissionId Int\n\n  // Relations\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n  // @@map(\"user_permissions\")\n\n  // Composite primary key\n  @@id([userId, permissionId])\n  // Optional index\n  @@index([permissionId])\n}\n\n// --- Core Blog Content Models ---\n\nmodel Post {\n  id        Int     @id @default(autoincrement())\n  title     String\n  slug      String  @unique // Bagian URL yang SEO-friendly\n  content   String  @db.Text // Tipe TEXT untuk konten panjang\n  published Boolean @default(false) // Status draft/published\n  imagePath String? // Path ke gambar lokal (camelCase)\n\n  // Relations\n  authorId Int // Foreign key (camelCase)\n  author   User @relation(fields: [authorId], references: [id], onDelete: Cascade) // Jika user dihapus, hapus postnya\n\n  categoryId Int? // Foreign key (camelCase), opsional\n  category   Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull) // Jika kategori dihapus, set categoryId post jadi NULL\n\n  comments Comment[] // Relasi ke komentar post\n  tags     PostsTags[] // Relasi ke tag post via tabel pivot\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Optional index\n  @@index([authorId])\n  @@index([categoryId])\n}\n\nmodel Category {\n  id   Int    @id @default(autoincrement())\n  name String @unique\n  slug String @unique\n\n  // Relations\n  posts Post[] // Relasi ke postingan dalam kategori ini\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Tag {\n  id   Int    @id @default(autoincrement())\n  name String @unique\n  slug String @unique\n\n  // Relations\n  posts PostsTags[] // Relasi ke postingan dengan tag ini via tabel pivot\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// --- Pivot Table for Post <-> Tag (Many-to-Many) ---\n// Note: Pivot tables often don't need explicit timestamps.\n\nmodel PostsTags {\n  postId Int // Foreign key (camelCase)\n  tagId  Int // Foreign key (camelCase)\n\n  // Relations\n  post Post @relation(fields: [postId], references: [id], onDelete: Cascade)\n  tag  Tag  @relation(fields: [tagId], references: [id], onDelete: Cascade)\n  // @@map(\"posts_tags\")\n\n  // Composite primary key\n  @@id([postId, tagId])\n  // Optional index\n  @@index([tagId])\n}\n\n// --- Comment Model ---\n\nmodel Comment {\n  id               Int    @id @default(autoincrement())\n  content          String @db.Text\n  moderationStatus String @default(\"pending\") @map(\"moderation_status\") // contoh: \"pending\", \"approved\", \"rejected\" (map ke snake_case jika perlu)\n\n  // Relations\n  postId Int // Foreign key (camelCase)\n  post   Post @relation(fields: [postId], references: [id], onDelete: Cascade) // Jika post dihapus, hapus komentarnya\n\n  authorId Int // Foreign key (camelCase)\n  author   User @relation(fields: [authorId], references: [id], onDelete: Cascade) // Jika user dihapus, hapus komentarnya\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Optional index\n  @@index([postId])\n  @@index([authorId])\n}\n",
